package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTeDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("చెడ్డ పొరుగువారి నుండి శరణార్థి", "ఓ అల్లాహ్, శాశ్వత నివాస స్థలంలో చెడ్డ పొరుగువారి నుండి నేను నిన్ను ఆశ్రయిస్తున్నాను, ఎందుకంటే ప్రయాణంలో ఉన్న పొరుగువాడు ముందుకు వెళ్తాడు.", "చెడ్డ పొరుగువారి నుండి రక్షణ కోసం.", "దీని నుండి ఆశ్రయం పొందాలని ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఆదేశించారు."),
        "dua_ishfi_abdak" to DuaText("అనారోగ్యంతో ఉన్న వ్యక్తి కోలుకోవడానికి", "ఓ అల్లాహ్, నీ సేవకుడిని నయం చేయి, తద్వారా అతను నీ కోసం శత్రువును ఎదుర్కోవచ్చు లేదా నీ కోసం ప్రార్థన చేయడానికి నడవవచ్చు.", "అనారోగ్యంతో ఉన్న వ్యక్తిని సందర్శించినప్పుడు.", "రోగుల కోసం ఇలా చెప్పడం ప్రవక్త సల్లల్లాహు అలైహి వసల్లం నేర్పించారు."),
        "dua_la_mania" to DuaText("మీరు ఇచ్చేదాన్ని ఎవరూ ఆపలేరు", "అల్లాహ్ తప్ప ఎవరూ పూజింపబడటానికి హక్కు లేదు, ఒంటరిగా, భాగస్వామి లేకుండా. ఆధిపత్యం ఆయనదే, ప్రశంసలు ఆయనదే, అన్నింటిపై ఆయనకు అధికారం ఉంది. అల్లాహ్వే, నీవు ఇచ్చేదాన్ని ఎవరూ అడ్డుకోరు, నీవు దాచిపెట్టినదాన్ని ఎవరూ ఇవ్వలేరు, ధనవంతుల సంపద నీకు వ్యతిరేకంగా ఏ ప్రయోజనం లేదు.", "తప్పనిసరి ప్రార్థన యొక్క సలాం తరువాత.", "ప్రతి తప్పనిసరి ప్రార్థన తర్వాత ప్రవక్త ఈ విధంగా చెప్పారు."),
        "dua_slaughtering" to DuaText("ఒక జంతువును చంపేటప్పుడు", "అల్లాహ్ పేరిట, మరియు అల్లాహ్ గొప్పవాడు.", "ఒక జంతువును బలి ఇచ్చేటప్పుడు లేదా చంపేసేటప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం త్యాగం సమయంలో బిస్మిల్లా మరియు తక్బీర్ చెప్పారు."),
        "dua_undressing" to DuaText("దుస్తులు తీసేసేటప్పుడు", "అల్లాహ్ పేరిట.", "బట్టలు ఉతకడం (గుస్లు లేదా మార్చడం కోసం).", "ఇది జిన్ కళ్ళకు మరియు వ్యక్తి యొక్క ప్రైవేట్ పార్ట్స్ మధ్య తెరగా మారుతుంది."),
        "dua_ilbas_jadidan" to DuaText("కొత్త దుస్తులు ధరించిన వ్యక్తిని చూడటం", "కొత్త దుస్తులు ధరించండి, ప్రశంసనీయం గా జీవించండి మరియు అమరవీరుడిగా మరణించండి.", "కొత్త దుస్తులు ధరించిన ముస్లిం సోదరుడిని చూసినప్పుడు.", "ఉమర్ (ర) ను కొత్త దుస్తులు ధరించి చూసినప్పుడు ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ దుఆ చేశారు."),
        "dua_hajj_la_riya" to DuaText("ప్రదర్శన లేకుండా హజ్", "ఓ అల్లాహ్, (దానిని) ఎటువంటి ప్రదర్శన మరియు కీర్తిని కోరుకోని హజ్గా చేయండి.", "హజ్ కోసం ఉద్దేశించినప్పుడు నిజాయితీ కోసం.", "హజ్ సమయంలో ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ దుఆ చేశారు."),
        "dua_q_muslimayni_laka" to DuaText("ఇబ్రహీం మరియు ఇస్మాయిల్ (ఏఎస్) యొక్క దువా-మమ్మల్ని విధేయతతో ఉండేలా చేయండి", "మా ప్రభూ, మాకు మరియు మా సంతానం ఇద్దరికీ మీరు మరియు మీకు విధేయత చూపించే జాతిగా చేయండి. మా ఆరాధన ఆచారాలను మాకు చూపించండి మరియు మా పశ్చాత్తాపాన్ని అంగీకరించండి. నిశ్చయంగా, మీరు పశ్చాత్తాపానికి నాయకుడు, దయగలవారు.", "తన కోసం, తన వారసుల కోసం లొంగుబాటు అయ్యే ద్వయం.", "కాబా నిర్మిస్తున్నప్పుడు ఈ దుఆ తయారు చేయబడింది."),
        "dua_q_iftah_baynana" to DuaText("షుఐబ్ (ఏఎస్) యొక్క దువా-మా మధ్య న్యాయమూర్తి", "మా ప్రభూ, మాకు మరియు మా ప్రజలకు మధ్య నిజాయితీగా తీర్పు చెప్పండి, మరియు మీరు ఉత్తమ న్యాయమూర్తులు.", "నిజం మరియు అబద్ధాల మధ్య తీర్పు కోసం.", "షుఐబ్ (ఏఎస్) యొక్క దుఆ అతని ప్రజలు తిరస్కరించినప్పుడు."),
        "dua_q_la_akuna_zahiran" to DuaText("మూసా (ఏఎస్) యొక్క దువా-నేరస్థులకు ఎప్పుడూ సహాయకుడు కాదు", "నా ప్రభూ, నీవు నాపై చూపిన అనుగ్రహం కారణంగా, నేను నేరస్థులకు ఎప్పటికీ సహాయకుడిగా ఉండను.", "అల్లాహ్ యొక్క ఆశీర్వాదాలకు కృతజ్ఞత మరియు తప్పు చేసిన వారికి సహాయం చేయకూడదని ప్రతిజ్ఞ.", "మూసా (అ. స.) పశ్చాత్తాపం తరువాత చేసిన ప్రతిజ్ఞ."),
        "dua_q_nuh_unsurni" to DuaText("నూహ్ (అ. స.) యొక్క దువా-నాకు సహాయం చేయండి, వారు నన్ను తిరస్కరిస్తారు", "నా ప్రభూ, నాకు సహాయం చెయ్యి, ఎందుకంటే వారు నన్ను తిరస్కరించారు.", "ప్రజలు మిమ్మల్ని తిరస్కరించి, సత్యాన్ని తిరస్కరించినప్పుడు.", "నూహ్ (అ. స.) యొక్క దుఆ, దీనికి సమాధానం ఇవ్వబడింది."),
        "dua_q_ihkum_bil_haqq" to DuaText("నా ప్రభూ, సత్యంతో తీర్పు తీర్చుము.", "నా ప్రభూ, నిజాయితీతో తీర్పు తీర్చుము. మరియు మా ప్రభువు అత్యంత కరుణామయుడు, మీరు వివరించేదానికి వ్యతిరేకంగా అతని సహాయం కోరబడుతుంది.", "అబద్ధాలు, తప్పుడు ఆరోపణల నేపథ్యంలో.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం కు ఒక దుఆ బోధించారు."),
        "dua_ghalabatid_dayn" to DuaText("మొండి బకాయిల నుండి, శత్రువుల నుండి శరణార్థులు", "ఓ అల్లాహ్, రుణభారం నుండి, శత్రువుచే ఓడించబడటం నుండి మరియు శత్రువుల గర్వం నుండి నేను నీలో ఆశ్రయం పొందుతున్నాను.", "రుణ భారం నుండి రక్షణ మరియు శత్రువుల ఆధిపత్యం.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ విషయాల నుండి ఆశ్రయం పొందేవారు."),
        "dua_faqr_qillah_dhillah" to DuaText("పేదరికం మరియు అవమానాల నుండి శరణార్ధులు", "ఓ అల్లాహ్, పేదరికం, కొరత మరియు అవమానాల నుండి, ఇతరులకు అన్యాయం చేయడం లేదా అన్యాయం చేయబడటం నుండి నేను నీకు ఆశ్రయం కోరుతున్నాను.", "కష్టాలు, కోరికలు మరియు అవమానాల నుండి సురక్షితంగా ఉండండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం బోధించిన ఆశ్రయం."),
        "dua_five_things_new_muslim" to DuaText("క్షమించండి, దయ చూపండి, మార్గనిర్దేశం చేయండి, నయం చేయండి, అందించండి", "ఓ అల్లాహ్, నన్ను క్షమించు, నన్ను కరుణించు, నాకు మార్గనిర్దేశం చేయి, నాకు శ్రేయస్సు ఇవ్వు మరియు నాకు పోషణ చేయి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం కొత్త ముస్లింలకు ప్రార్థనతో పాటు ఈ దుఆ బోధించారు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఇలా అన్నారుః ఈ పదాలు మీ కోసం ఈ ప్రపంచాన్ని మరియు పరలోకాన్ని సేకరిస్తాయి."),
        "dua_ruku_laka_raka_tu" to DuaText("రుకులో-మీకు నేను వంగి", "ఓ అల్లాహ్, నేను నీకు నమస్కరించాను, నేను నిన్ను విశ్వసించాను, నీకు సమర్పించాను. నా వినికిడి, నా దృష్టి, నా మనస్సు, నా ఎముకలు, నా నరాలు నీ ముందు వినయంగా ఉన్నాయి.", "రుకులో (ముఖ్యంగా స్వచ్ఛంద ప్రార్థనలలో).", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం దీనిని రుకులో పఠించారు."),
        "dua_sujood_laka_sajadtu" to DuaText("సుజూద్ లో-టు యు నేను ప్రోస్ట్రేట్ చేశాను", "ఓ అల్లాహ్, నేను నీకు సాష్టాంగ నమస్కారం చేశాను, నేను నిన్ను విశ్వసించాను, నీకు విధేయత చూపాను. దానిని సృష్టించిన, దానిని ఆకృతి చేసిన, దాని వినికిడి మరియు దృష్టిని తీసుకువచ్చిన వ్యక్తికి నా ముఖం సాష్టాంగ నమస్కారం చేసింది. సృష్టికర్తలలో ఉత్తమమైన అల్లాహ్ ధన్యుడు.", "సుజూద్ లో (ముఖ్యంగా స్వచ్ఛంద ప్రార్థనలలో).", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం దీనిని సుజూద్ లో పఠించారు."),
        "dua_ruku_sujood_subhanaka" to DuaText("మహిమ నీకు, మా ప్రభూ-నన్ను క్షమించండి", "మా ప్రభువైన అల్లాహ్, నీకు మహిమ కలగాలి, నీకు స్తుతి. ఓ అల్లాహ్, నన్ను క్షమించు.", "రుకు మరియు సుజూద్ లో.", "ఆయిషా (ర): ప్రవక్త సల్లల్లాహు అలైహి వసల్లం తరచుగా దీనిని రుకు మరియు సుజూద్ భాషలలో చెప్పారు."),
        "dua_q_musa_li_akhi" to DuaText("మూసా (అ. స.) యొక్క దువా-నన్ను, నా సోదరుడిని క్షమించండి", "నా ప్రభూ, నన్ను, నా సోదరుడిని క్షమించి, మమ్మల్ని నీ దయలో చేర్చుకో, ఎందుకంటే నీవు కరుణామయుడిలో అత్యంత దయగలవాడవు.", "తన కోసం, తన సోదరుడు లేదా ప్రియమైన వారిని క్షమించండి.", "హారూన్ (AS) కోసం మూసా (AS) యొక్క దుఆ."),
        "dua_q_ufawwidu_amri" to DuaText("నేను నా వ్యవహారాన్ని అల్లాహ్కు అప్పగిస్తున్నాను.", "నేను నా వ్యవహారాన్ని అల్లాహ్కు అప్పగిస్తున్నాను. నిశ్చయంగా అల్లాహ్ తన సేవకులను చూసేవాడు.", "ప్రజలు మిమ్మల్ని వ్యతిరేకించినప్పుడు, ఆ విషయాన్ని అల్లాహ్కు వదిలేయాలి.", "ఫరో ప్రజల నుండి విశ్వాసి యొక్క మాటలు; అల్లాహ్ అప్పుడు వారి దుష్ట కుట్రల నుండి అతన్ని రక్షించాడు."),
        "dua_q_hawariyyun" to DuaText("శిష్యుల దుఆ-సాక్షులతో మమ్మల్ని నమోదు చేయండి", "మా ప్రభూ, నీవు అవతరింపజేసిన దానిని మేము విశ్వసించాము, మరియు మేము దూతను అనుసరించాము, కాబట్టి మమ్మల్ని సాక్షులలో నమోదు చేసుకోండి.", "విశ్వాసంలో స్థిరత్వం కోసం మరియు దూతను అనుసరించడానికి.", "ఈసా (AS) శిష్యుల దుఆ."),
        "dua_q_la_tukhzini" to DuaText("ఇబ్రహీం (అ. స.) యొక్క దువా-నన్ను అవమానించవద్దు", "వారు పునరుత్థానం చేయబడిన రోజున నన్ను అవమానించవద్దు.", "పునరుత్థాన రోజున అవమానము నుండి సురక్షితంగా ఉండటానికి.", "పరాయణానికి ఇబ్రహీం (అ. స.) యొక్క దుఆ."),
        "dua_iftar_laka_sumtu" to DuaText("ఇఫ్తార్-మీ కోసం నేను ఉపవాసం ఉన్నాను", "ఓ అల్లాహ్, నేను నీ కోసం ఉపవాసం చేశాను మరియు నీ ఆహారంతో నా ఉపవాసాన్ని విచ్ఛిన్నం చేస్తున్నాను.", "ఉపవాసం విచ్ఛిన్నం చేసేటప్పుడు (ప్రసిద్ధ ఇఫ్తార్ దుఆ).", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఇఫ్తార్ సందర్భంగా ఇలా అన్నారు. ఇది ఇతర కథనాలు బలపరిచే ఒక ముర్సా కథనం; ఇఫ్తార్ సమయంలో పఠించడం అనేది హనాఫీలు మరియు మెజారిటీల ఆచారం."),
        "dua_iftar_ibn_umar" to DuaText("ఇఫ్తార్-మీ అపార దయతో, నన్ను క్షమించండి", "ఓ అల్లాహ్, నన్ను క్షమించమని అన్ని విషయాలను కలిగి ఉన్న నీ దయ ద్వారా నేను నిన్ను అడుగుతున్నాను.", "ఇఫ్తార్ సమయంలో-అబ్దుల్లా ఇబ్న్ అమర్ (రా) ఈ దుఆ చేసాడు; ఇఫ్తార్ వద్ద ఉపవాసం ఉన్న వ్యక్తి యొక్క దుఆ తిరస్కరించబడదు.", "హదీస్ః ఇఫ్తార్ సమయంలో ఉపవాసం ఉన్న వ్యక్తి యొక్క దుఆ తిరస్కరించబడదు."),
        "dua_inni_saim" to DuaText("ఉపవాసం చేస్తున్నప్పుడు రెచ్చగొట్టినప్పుడు", "నేను ఉపవాసం ఉన్నాను, ఉపవాసం ఉన్నాను.", "ఉపవాసం ఉన్నప్పుడు ఎవరైనా మిమ్మల్ని అవమానించినప్పుడు లేదా మీతో గొడవపడినప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఇలా అన్నారుః ఉపవాసం అనేది ఒక కవచం, కాబట్టి ఉపవాసం ఉన్న వ్యక్తి అశ్లీలంగా మాట్లాడకూడదు లేదా అజ్ఞానంగా వ్యవహరించకూడదు-ఎవరైనా గొడవపడితే, దీనిని రెండుసార్లు చెప్పండి."),
        "dua_eid_takbeer" to DuaText("ఈద్ కు వెళ్లే మార్గంలో తక్బీర్", "అల్లాహ్ గొప్పవాడు, అల్లాహ్ గొప్పవాడు, అల్లాహ్ తప్ప దేవుడు లేడు, అల్లాహ్ గొప్పవాడు, అల్లాహ్ గొప్పవాడు, మరియు అన్ని ప్రశంసలు అల్లాహ్ కోసం.", "చంద్రుని దర్శనం రాత్రి నుండి ఈద్ అల్-ఫితర్ ప్రార్థన వరకు, ముఖ్యంగా ఈద్ మైదానానికి వెళ్లే మార్గంలో.", "ఖురాన్ ఆదేశంః'మీరు లెక్కింపు పూర్తి చేసి అల్లాహ్ యొక్క గొప్పతనాన్ని ప్రకటించడానికి'(అల్-బఖరా 2:185). ఇబ్న్ మసూద్ (రా) ఈ తక్బీర్ చెప్పారు."),
        "dua_ahsin_aqibatana" to DuaText("అన్ని విషయాల్లో మన లక్ష్యాన్ని బాగుచేయండి", "ఓ అల్లాహ్, అన్ని విషయాలలో మన లక్ష్యాన్ని బాగుచేయుము, ఈ లోకంలో అవమానము నుండి, పరలోకంలో శిక్ష నుండి మమ్మల్ని రక్షించండి.", "ప్రతి విషయంలో మంచి ఫలితం కోసం.", "విచారణకు ముందు ఈ దుఆ చేసి మరణించేవాడు మరణిస్తాడు (విచారణ నుండి సురక్షితంగా)."),
        "dua_fadlika_wa_rahmatik" to DuaText("నేను మీ అనుగ్రహం మరియు దయను కోరుతున్నాను", "ఓ అల్లాహ్, నేను నీ అనుగ్రహం మరియు నీ దయను కోరుతున్నాను, ఎందుకంటే నీవు తప్ప మరెవరూ వాటిని కలిగి లేరు.", "ఏర్పాటు మరియు దయ కోసం అడిగినప్పుడు.", "ఆహారం లేనప్పుడు అతిథులు ప్రవక్త సలీం అలీహ్ వస్సం వద్దకు వచ్చారు; ఆయన ఈ దుఆ తయారు చేసి, ఆపై ఒక బహుమతి వచ్చింది."),
        "dua_allahu_akbar_kabira_2696" to DuaText("బెడౌయిన్కు నేర్పిన పదాలు", "అల్లాహ్ తప్ప ఎవరూ ఆరాధించబడటానికి హక్కు లేదు, ఒంటరిగా, భాగస్వామి లేకుండా. అల్లాహ్ గొప్పవాడు, గొప్పవాడు, అల్లాహ్ కోసం సమృద్ధిగా ప్రశంసలు ఉన్నాయి, ప్రపంచాలకు ప్రభువైన అల్లాహ్ మహిమ కలిగి ఉన్నాడు, మరియు సర్వశక్తిమంతుడైన, జ్ఞానవంతుడైన అల్లాహ్ తప్ప శక్తి లేదా శక్తి లేదు.", "ఒక బెడౌయిన్కు నేర్పించిన ధిక్ర్ మరియు దుఆ యొక్క సమగ్ర పదబంధం.", "దీని తరువాత ఆయనకు'అల్లాహుమాఘ్ఫిర్ లీ వార్హమ్నీ వాహ్దిని వార్జుక్నీ'అని చెప్పడం నేర్పించారు."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("నేను ముందు మరియు తరువాత పంపిన వాటిని క్షమించండి.", "ఓ అల్లాహ్, నేను ముందు, తరువాత చేసిన పాపాలు, నేను రహస్యంగా చేసినవి, బహిరంగంగా చేసినవి, నా మితిమీరిన పనులు, నాకంటే బాగా తెలిసినవి నన్ను క్షమించు. నీవే ముందుకు తెచ్చేవాడు, వెనక్కి పెట్టేవాడు, నీవు తప్ప మరో దేవుడు లేడు.", "తాషహుద్ మరియు సలావత్ తరువాత, సలాం ముందు.", "ప్రవాది సల్లల్లాహు అలైహి వసల్లం ప్రార్థన ముగింపులో, తాషాహ్హుద్ మరియు సలాం మధ్య దీనిని పఠించారు."),
        "dua_jiddi_wa_hazli" to DuaText("నా గంభీరతను, నా నీచత్వాన్ని క్షమించండి.", "ఓ అల్లాహ్, నేను చేసిన పాపాలను, పొరపాటున, ఉద్దేశపూర్వకంగా, తీవ్రంగా, తమాషాగా, క్షమించండి-అవన్నీ నాలోనే ఉన్నాయి.", "తెలిసిన మరియు తెలియని అన్ని రకాల పాపాలకు క్షమాపణ.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క సమగ్ర ఇస్తిగ్ఫర్."),
        "dua_rising_ruku_mil" to DuaText("రుకు తరువాత-స్వర్గాలను నింపడం", "మా ప్రభూ, ఆకాశాలను నింపుతూ, భూమిని నింపుతూ, ఆ తరువాత మీరు కోరుకునేదంతా నింపుతూ, సమస్త స్తుతులు నీకే చెందుతాయి.", "రుకు నుండి లేచిన తరువాత,'రబ్బానా లాకల్-హమ్ద్'తో కలిసి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం రుకు నుండి లేచినప్పుడు ఈ మాట చెప్పారు."),
        "dua_istiftah_kabira" to DuaText("అల్లాహ్ గొప్పవాడు, ఎంతో ప్రశంసించబడ్డాడు.", "అల్లాహ్ గొప్పవాడు, గొప్పవాడు; అల్లాహ్ కోసం సమృద్ధిగా ప్రశంసలు ఉన్నాయి; మరియు ఉదయం మరియు సాయంత్రం అల్లాహ్ మహిమ కలిగి ఉంటాడు.", "ప్రార్థనను ప్రారంభించేటప్పుడు (ప్రారంభ ప్రశంసలలో ఒక రూపం).", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఇలా అన్నారుః దాని కోసం స్వర్గం యొక్క ద్వారాలు తెరవబడ్డాయి."),
        "dua_q_ashku_bathhi" to DuaText("యాకుబ్ (అ. స.) యొక్క దువా-నేను అల్లాహ్కు మాత్రమే ఫిర్యాదు చేస్తాను.", "నేను నా బాధను, నా బాధను అల్లాహ్కు మాత్రమే ఫిర్యాదు చేస్తున్నాను.", "లోతైన దుఃఖం మరియు విభజనలో.", "యూసుఫ్ (ఏఎస్) నుండి విడిపోయినప్పుడు యాకుబ్ (ఏఎస్) ఈ విషయం చెప్పాడు."),
        "dua_q_khayrun_hafiza" to DuaText("అల్లాహ్ ఉత్తమ రక్షకుడు.", "అల్లాహ్ ఉత్తమ రక్షకుడు, మరియు అతను దయగలవారిలో అత్యంత దయగలవాడు.", "పిల్లలు లేదా ప్రియమైన వారిని ప్రయాణానికి పంపేటప్పుడు.", "యాకుబ్ (అ. స.) తన కొడుకును అల్లాహ్కు అప్పగిస్తూ ఈ విషయం చెప్పాడు."),
        "dua_q_aqraba_rashada" to DuaText("నా ప్రభువు నాకు కుడివైపుకు మరింత దగ్గరగా మార్గనిర్దేశం చేయుగాక", "బహుశా నా ప్రభువు నాకు సరైన ప్రవర్తనకు ఇంతకంటే దగ్గరగా ఉన్నదానికి మార్గనిర్దేశం చేస్తాడు.", "కొన్ని విషయాలలో మెరుగైన మార్గాన్ని వెతుకుతున్నప్పుడు.", "మర్చిపోయిన తర్వాత ఈ విషయం చెప్పమని ప్రవక్త సల్లల్లాహు అలైహి వసల్లం కు చెప్పబడింది."),
        "dua_q_sawa_as_sabil" to DuaText("మూసా (అ. స.) యొక్క దువా-నాకు సరైన మార్గాన్ని చూపండి", "బహుశా నా ప్రభువు నాకు సరైన మార్గాన్ని చూపిస్తాడు.", "కొత్త ప్రయాణానికి లేదా తెలియని రహదారికి బయలుదేరినప్పుడు.", "మూసా (ఏఎస్) మాద్యాన్ వైపు తిరిగేటప్పుడు ఈ విషయం చెప్పాడు."),
        "dua_q_not_among_wrongdoers" to DuaText("నన్ను తప్పు చేసేవారిలో పెట్టకండి", "నా ప్రభూ, నన్ను అన్యాయస్థులలో ఒకరిగా ఉంచవద్దు.", "ఒక వ్యక్తిని దోషుల నుండి వేరుగా ఉంచమని అల్లాహ్ను కోరుతూ ఒక దుఆ.", "ఒక వ్యక్తిని దోషుల నుండి వేరుగా ఉంచమని అల్లాహ్ను కోరుతూ ఒక దుఆ."),
        "dua_q_do_not_make_us_trial" to DuaText("మమ్మల్ని విచారణకు గురి చేయవద్దు", "మా ప్రభూ, మాకు అవిశ్వాసుల కోసం ఒక పరీక్షగా మార్చవద్దు, మరియు మాకు క్షమించండి, మా ప్రభూ. నిశ్చయంగా నీవు సర్వశక్తిమంతుడవు, వివేకుడవు.", "ఇబ్రహీం (అ. స.) మరియు అతని సహచరుల దుఆ.", "ఇబ్రహీం (అ. స.) మరియు అతని సహచరుల దుఆ."),
        "dua_morning_witness" to DuaText("తౌహీదుకు ఉదయం సాక్షి", "ఓ అల్లాహ్, నేను ఉదయం ప్రవేశించాను, మీ సింహాసనం యొక్క వాహకులు, మీ దేవదూతలు మరియు మీ సృష్టి అంతా, మీరు అల్లాహ్ అని సాక్ష్యమివ్వడానికి, మీరు తప్ప ఏ దేవుడు లేడని, ఒంటరిగా, భాగస్వామి లేకుండా, మరియు ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం మీ సేవకుడు మరియు దూత అని.", "ఉదయం నాలుగు సార్లు ఇలా చెప్పారని కథనం పేర్కొంది.", "ఉదయం నాలుగు సార్లు ఇలా చెప్పారని కథనం పేర్కొంది."),
    )
}
